    dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    length = 2
    leg = 0
    while length <= 4 * n:
        dr, dc = dirs[leg % 4]
        for _ in range(length):
            if 0 <= r < n and 0 <= c < n and grid[r][c] != 2:
                out[r][c] = 3
            r += dr
            c += dc
        leg += 1
        if leg % 2 == 0:
            length += 2
    return out
